examples.template:
Column(
    modifier = Modifier
        .fillMaxWidth()
        .dragAndDropTarget(
            shouldStartDragAndDrop = { event -> event.mimeTypes().any { type -> accept.any { pattern -> type == pattern || (pattern.endsWith("/*") && type.startsWith(pattern.dropLast(1))) } } },
            target = target,
        )
        .background(if (targeted) MonarchTheme.colors.accentSubtle else Color.Transparent, MonarchTheme.shapes.md),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
) {
    MonarchFileUpload(
        onFiles = { accepted, _ ->
            items = items + accepted.map { MonarchFileListItem(id = it.uri.toString(), name = it.name, sizeBytes = it.size) }
        },
        variant = MonarchFileUploadVariant.Compact,
        accept = accept,
        maxSize = {{maxSize}},
        hint = {{hint}},
        labels = MonarchFileUploadLabels(browse = {{browse}}),
    )
    MonarchFileList(items = items, modifier = Modifier.height(96.dp), label = {{listLabel}})
}

examples.setupTemplate:
val accept = listOf({{accept.0}}, {{accept.1}})
var targeted by remember { mutableStateOf(false) }
var items by remember {
    mutableStateOf(
        listOf(
            MonarchFileListItem(id = {{files.0.id}}, name = {{files.0.name}}, sizeBytes = {{files.0.size}}),
        ),
    )
}
val target = remember {
    object : DragAndDropTarget {
        override fun onEntered(event: DragAndDropEvent) { targeted = true }
        override fun onExited(event: DragAndDropEvent) { targeted = false }
        override fun onEnded(event: DragAndDropEvent) { targeted = false }
        override fun onDrop(event: DragAndDropEvent): Boolean {
            // The app requests permissions and reads each uri with MonarchPickedFile.of here, then adds it to items.
            return true
        }
    }
}

